def _smoke_is_stub(text: str) -> bool:
    body = re.sub(r"(?m)^\s*(#|//).*$", "", text)
    body = re.sub(r"^\s*#!.*$", "", body, flags=re.M).strip()
    return (not body) or body in {"exit 0", "exit 0;", "true", ":"}

